import React, { useState } from "react";
import Navbar from "./navbar";
import Style1 from "./result.module.css";

function ViewResult1() {
  const [roll, setRoll] = useState("");
  const [class1, setClass1] = useState(""); // class select
  const [exam, setExam] = useState(""); // exam select
  const [result, setResult] = useState(null);

  const handleSubmit = async () => {
    if (!roll || !class1 || !exam) {
      alert("Please fill all fields");
      return;
    }

    try {
      const query = `roll=${roll}&class1=${class1}&exam=${exam}`;
      const res = await fetch(`http://localhost:8009/api/results/search?${query}`);
      const data = await res.json();
      setResult(data);
    } catch (err) {
      console.error(err);
      alert("Error fetching result");
    }
  };

  return (
    <>
      <div>
        <Navbar />
        <div className={Style1.main}>
          <h1 className={Style1.heading}>School Results</h1>
          <div className={Style1.input}>
            <div className={Style1.arrange}>
              <label className={Style1.label}>Roll no</label>
              <input
                className={Style1.input1}
                type="text"
                placeholder="enter the roll no"
                value={roll}
                onChange={(e) => setRoll(e.target.value)}
              />
            </div>

            <div className={Style1.arrange}>
              <label className={Style1.label}>Class</label>
              <select
                className={Style1.input1}
                value={class1}
                onChange={(e) => setClass1(e.target.value)}
              >
                <option value="">-- Select Class --</option>
                <option value="10">10</option>
                <option value="9">9</option>
                <option value="8">8</option>
                <option value="7">7</option>
              </select>
            </div>

            <div className={Style1.arrange}>
              <label className={Style1.label}>Exam type</label>
              <select
                className={Style1.input1}
                value={exam}
                onChange={(e) => setExam(e.target.value)}
              >
                <option value="">-- Select Exam --</option>
                <option value="midterm">Midterm</option>
                <option value="final">Final</option>
                <option value="quiz">Quiz</option>
                <option value="practical">Practical</option>
              </select>
            </div>

            <button className={Style1.submit} onClick={handleSubmit}>
              Submit
            </button>
          </div>

          {/* Display result */}
          {result && result.length > 0 && (
            <div style={{ marginTop: "20px" }}>
              <h3>Result:</h3>
              <table>
                <thead>
                  <tr>
                    <th>Roll</th>
                    <th>Class</th>
                    <th>Exam</th>
                    <th>Telugu</th>
                    <th>Hindi</th>
                    <th>English</th>
                    <th>Maths</th>
                    <th>Science</th>
                    <th>Social</th>
                  </tr>
                </thead>
                <tbody>
                  {result.map((r, index) => (
                    <tr key={index}>
                      <td>{r.roll}</td>
                      <td>{r.class1}</td>
                      <td>{r.exam}</td>
                      <td>{r.telugu}</td>
                      <td>{r.hindi}</td>
                      <td>{r.english}</td>
                      <td>{r.maths}</td>
                      <td>{r.science}</td>
                      <td>{r.social}</td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          )}

          {result && result.length === 0 && <p>No result found</p>}
        </div>
      </div>
    </>
  );
}

export default ViewResult1;
